describe('Checkbox States - Checkbox Interaction', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
  });

  it('should toggle checkbox states correctly when interacting with checkboxes', () => {
    // Verify initial state
    cy.get('[type="checkbox"]').first().should('not.be.checked');
    cy.get('[type="checkbox"]').last().should('be.checked');

    // Check the first checkbox
    cy.get('[type="checkbox"]').first().click();
    cy.get('[type="checkbox"]').first().should('be.checked');
    cy.get('[type="checkbox"]').last().should('be.checked');

    // Uncheck the second checkbox
    cy.get('[type="checkbox"]').last().click();
    cy.get('[type="checkbox"]').last().should('not.be.checked');
    cy.get('[type="checkbox"]').first().should('be.checked');

    // Check the second checkbox again
    cy.get('[type="checkbox"]').last().click();
    cy.get('[type="checkbox"]').last().should('be.checked');
    cy.get('[type="checkbox"]').first().should('be.checked');
  });

  it('should maintain correct checkbox states when toggling between checkboxes', () => {
    // Verify initial state
    cy.get('[type="checkbox"]').first().should('not.be.checked');
    cy.get('[type="checkbox"]').last().should('be.checked');

    // Check the first checkbox
    cy.get('[type="checkbox"]').first().click();
    cy.get('[type="checkbox"]').first().should('be.checked');
    cy.get('[type="checkbox"]').last().should('be.checked');

    // Uncheck the first checkbox
    cy.get('[type="checkbox"]').first().click();
    cy.get('[type="checkbox"]').first().should('not.be.checked');
    cy.get('[type="checkbox"]').last().should('be.checked');

    // Check the second checkbox
    cy.get('[type="checkbox"]').last().click();
    cy.get('[type="checkbox"]').last().should('be.checked');
    cy.get('[type="checkbox"]').first().should('not.be.checked');

    // Uncheck the second checkbox
    cy.get('[type="checkbox"]').last().click();
    cy.get('[type="checkbox"]').last().should('not.be.checked');
    cy.get('[type="checkbox"]').first().should('not.be.checked');
  });
});
